// Package validate is a Go port of the two validators that ship with Cloudflare's security-audit skill
// (validate-findings.cjs and validate-coverage-ledger.cjs, pinned commit c1c8a8c, MIT). The rules, limits and
// messages follow the upstream scripts so the same documents pass or fail; golden tests generated by running the
// upstream scripts keep them aligned (see testdata/golden and scripts/gen-golden.cjs).
package validate

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"unicode"

	"golang.org/x/text/unicode/norm"

	"github.com/xsec-labs/xsec-plugin-code-audit/sidecar/internal/jsonv"
)

// Limits are the error cap shared by both validators.
const MaxErrors = 100

// defaultIgnorable is Unicode's Default_Ignorable_Code_Point.
var defaultIgnorable = &unicode.RangeTable{
	R16: []unicode.Range16{
		{Lo: 0x00AD, Hi: 0x00AD, Stride: 1}, {Lo: 0x034F, Hi: 0x034F, Stride: 1}, {Lo: 0x061C, Hi: 0x061C, Stride: 1},
		{Lo: 0x115F, Hi: 0x1160, Stride: 1}, {Lo: 0x17B4, Hi: 0x17B5, Stride: 1}, {Lo: 0x180B, Hi: 0x180F, Stride: 1},
		{Lo: 0x200B, Hi: 0x200F, Stride: 1}, {Lo: 0x202A, Hi: 0x202E, Stride: 1}, {Lo: 0x2060, Hi: 0x206F, Stride: 1},
		{Lo: 0x3164, Hi: 0x3164, Stride: 1}, {Lo: 0xFE00, Hi: 0xFE0F, Stride: 1}, {Lo: 0xFEFF, Hi: 0xFEFF, Stride: 1},
		{Lo: 0xFFA0, Hi: 0xFFA0, Stride: 1}, {Lo: 0xFFF0, Hi: 0xFFF8, Stride: 1},
	},
	R32: []unicode.Range32{
		{Lo: 0x1BCA0, Hi: 0x1BCA3, Stride: 1}, {Lo: 0x1D173, Hi: 0x1D17A, Stride: 1}, {Lo: 0xE0000, Hi: 0xE0FFF, Stride: 1},
	},
}

func isDefaultIgnorable(r rune) bool { return unicode.Is(defaultIgnorable, r) }

// isVisibleRune is the upstream VISIBLE_CONTENT class: not White_Space, Cc, Cf or Default_Ignorable.
func isVisibleRune(r rune) bool {
	return !(unicode.Is(unicode.White_Space, r) || unicode.Is(unicode.Cc, r) || unicode.Is(unicode.Cf, r) || isDefaultIgnorable(r))
}

// unsafeDiagnostic is the upstream UNSAFE_DIAGNOSTIC_CHARACTER class: Cc, Cf, Cs, Zl, Zp, Default_Ignorable.
func unsafeDiagnostic(r rune) bool {
	return unicode.Is(unicode.Cc, r) || unicode.Is(unicode.Cf, r) || unicode.Is(unicode.Cs, r) ||
		unicode.Is(unicode.Zl, r) || unicode.Is(unicode.Zp, r) || isDefaultIgnorable(r)
}

// pathForbidden is PATH_FORBIDDEN_CHARACTER: Cc, Cf, Zl, Zp, Default_Ignorable.
func pathForbidden(r rune) bool {
	return unicode.Is(unicode.Cc, r) || unicode.Is(unicode.Cf, r) || unicode.Is(unicode.Zl, r) ||
		unicode.Is(unicode.Zp, r) || isDefaultIgnorable(r)
}

func hasValidScalars(s string) bool { return !jsonv.HasLoneSurrogate(s) }

// HasVisibleProse mirrors hasVisibleProse.
func HasVisibleProse(s string) bool {
	if !hasValidScalars(s) {
		return false
	}
	for _, r := range jsonv.Runes(s) {
		if isVisibleRune(r) {
			return true
		}
	}
	return false
}

// jsTrim is String.prototype.trim.
func jsTrim(s string) string {
	return strings.TrimFunc(s, func(r rune) bool {
		switch r {
		case '\t', '\n', '\v', '\f', '\r', ' ', 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
			return true
		}
		return r >= 0x2000 && r <= 0x200A
	})
}

// escapeUnsafe is escapeUnsafeDiagnosticCharacters.
func escapeUnsafe(s string) string {
	var b strings.Builder
	for _, r := range jsonv.Runes(s) {
		if unsafeDiagnostic(r) {
			if r <= 0xFFFF {
				fmt.Fprintf(&b, `\u%04x`, r)
			} else {
				fmt.Fprintf(&b, `\u{%x}`, r)
			}
			continue
		}
		b.WriteRune(r)
	}
	return b.String()
}

const maxDiagString = 256

// safeQuote mirrors safeQuote (strings are clipped by UTF-16 length like JS .slice).
func safeQuote(v *jsonv.Value) string {
	var s string
	switch {
	case v == nil:
		s = `"<undefined>"`
	case v.Kind == jsonv.String:
		str := v.S
		if jsonv.UTF16Len(str) > maxDiagString {
			str = sliceUTF16(str, maxDiagString) + "..."
		}
		var b strings.Builder
		b.WriteString(string(jsonv.Marshal(&jsonv.Value{Kind: jsonv.String, S: str}, "")))
		s = b.String()
	case v.Kind == jsonv.Null:
		s = "null"
	case v.Kind == jsonv.Bool:
		s = strconv.FormatBool(v.B)
	case v.Kind == jsonv.Number && !isNonFinite(v.N):
		s = jsonv.JSNumber(v.N)
	default:
		name := v.TypeName()
		if v.Kind == jsonv.Array {
			name = "array"
		}
		s = `"<` + name + `>"`
	}
	return escapeUnsafe(s)
}

func quoteStr(s string) string { return safeQuote(jsonv.Str(s)) }

func isNonFinite(f float64) bool {
	return f != f || f > 1.7976931348623157e308 || f < -1.7976931348623157e308
}

// sliceUTF16 returns the first n UTF-16 units of s (rounding down at a surrogate pair boundary).
func sliceUTF16(s string, n int) string {
	units := 0
	end := 0
	for i := 0; i < len(s); {
		r, size := decodeRune(s[i:])
		w := 1
		if r >= 0x10000 {
			w = 2
		}
		if units+w > n {
			break
		}
		units += w
		i += size
		end = i
	}
	return s[:end]
}

func decodeRune(s string) (rune, int) {
	rs := jsonv.Runes(s[:min(len(s), 4)])
	if len(rs) == 0 {
		return 0, 1
	}
	r := rs[0]
	size := len(string(r))
	if r >= 0xD800 && r <= 0xDFFF {
		size = 3
	}
	return r, size
}

// errList caps and escapes diagnostics like createErrorList.
type errList struct{ items []string }

func (e *errList) push(msgs ...string) {
	for _, m := range msgs {
		if len(e.items) >= MaxErrors {
			return
		}
		e.items = append(e.items, escapeUnsafe(m))
	}
}

func (e *errList) len() int { return len(e.items) }

// Path-safety patterns.
var (
	windowsReservedComponent = regexp.MustCompile(`(?i)^(?:con|prn|aux|nul|clock\$|conin\$|conout\$|com[1-9\x{b9}\x{b2}\x{b3}]|lpt[1-9\x{b9}\x{b2}\x{b3}])(?:\.|$)`)
	agentIDPattern           = regexp.MustCompile(`^[a-z0-9][a-z0-9_-]{0,63}$`)
	windowsReservedAgentID   = regexp.MustCompile(`^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$`)
	fingerprintPattern       = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._:/@+-]*$`)
)

// IsSafeRelativeSourcePath mirrors isSafeRelativeSourcePath / isSafeRelativePath.
func IsSafeRelativeSourcePath(v *jsonv.Value) bool {
	if !v.IsString() {
		return false
	}
	s := v.S
	if s == "" || !hasValidScalars(s) || jsTrim(s) != s {
		return false
	}
	for _, r := range jsonv.Runes(s) {
		if pathForbidden(r) {
			return false
		}
	}
	if strings.Contains(s, `\`) || strings.Contains(s, ":") {
		return false
	}
	if strings.HasPrefix(s, "/") || strings.HasPrefix(s, "~") {
		return false
	}
	for _, seg := range strings.Split(s, "/") {
		if seg == "" || seg == "." || seg == ".." || strings.HasSuffix(seg, " ") || strings.HasSuffix(seg, ".") || windowsReservedComponent.MatchString(seg) {
			return false
		}
	}
	return true
}

// IsSafeAgentID mirrors isSafeAgentId.
func IsSafeAgentID(v *jsonv.Value) bool {
	return v.IsString() && agentIDPattern.MatchString(v.S) && !windowsReservedAgentID.MatchString(v.S)
}

func isNFC(s string) bool { return norm.NFC.IsNormalString(s) }

// toUTF16 returns the UTF-16 code units of a WTF-8 string.
func toUTF16(s string) []uint16 {
	out := make([]uint16, 0, len(s))
	for _, r := range jsonv.Runes(s) {
		switch {
		case r >= 0x10000:
			r -= 0x10000
			out = append(out, uint16(0xD800+(r>>10)), uint16(0xDC00+(r&0x3FF)))
		default:
			out = append(out, uint16(r))
		}
	}
	return out
}

// UTF16Less orders strings like JavaScript's < (by UTF-16 code units), which is how the upstream validators
// require findings and ledger units to be sorted.
func UTF16Less(a, b string) bool { return utf16Greater(b, a) }
